import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.C8822HRV.js";const g=JSON.parse('{"title":"Greenfield product planning with an AI coding agent","description":"Use sdd greenfield for Spec-Driven Development of a new product—vision, requirements, feature backlog, and architecture in git—then implement F-001 with your AI coding agent.","frontmatter":{"title":"Greenfield product planning with an AI coding agent","description":"Use sdd greenfield for Spec-Driven Development of a new product—vision, requirements, feature backlog, and architecture in git—then implement F-001 with your AI coding agent.","head":[["meta",{"property":"og:title","content":"Greenfield product planning with an AI coding agent · sdd"}],["meta",{"property":"og:description","content":"Use sdd greenfield for Spec-Driven Development of a new product—vision, requirements, feature backlog, and architecture in git—then implement F-001 with your AI coding agent."}],["meta",{"property":"og:url","content":"https://harsha09.github.io/spec-driven-development/guides/greenfield/"}],["meta",{"property":"og:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["meta",{"name":"twitter:title","content":"Greenfield product planning with an AI coding agent · sdd"}],["meta",{"name":"twitter:description","content":"Use sdd greenfield for Spec-Driven Development of a new product—vision, requirements, feature backlog, and architecture in git—then implement F-001 with your AI coding agent."}],["meta",{"name":"twitter:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["link",{"rel":"canonical","href":"https://harsha09.github.io/spec-driven-development/guides/greenfield/"}]]},"headers":[],"relativePath":"guides/greenfield.md","filePath":"guides/greenfield.md","lastUpdated":1785895617000}'),n={name:"guides/greenfield.md"};function o(r,e,d,l,h,p){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="greenfield-product-planning-with-an-ai-coding-agent" tabindex="-1">Greenfield product planning with an AI coding agent <a class="header-anchor" href="#greenfield-product-planning-with-an-ai-coding-agent" aria-label="Permalink to &quot;Greenfield product planning with an AI coding agent&quot;">​</a></h1><p>You have a <strong>sentence</strong>, not a backlog. <strong><code>sdd greenfield</code></strong> is Spec-Driven Development for a <strong>new product</strong>: a small plan <em>before</em> you and your AI drown in code—then you build <strong>one backlog item at a time</strong>.</p><p>Plans land in the repo (<code>changes/</code> then <code>memory/</code> on complete), so the agent’s next session still has product context.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Best for</strong></td><td>Empty repo / brand-new MVP</td></tr><tr><td><strong>You’ll get</strong></td><td>Notes in <code>memory/</code> + a list of features like F-001</td></tr><tr><td><strong>Not for</strong></td><td>A single bug on an existing app → use <a href="./simple-feature">simple feature</a> or a hotfix</td></tr></tbody></table><blockquote><p><strong>Picture it:</strong> idea → short plan → list of features → simple architecture → <code>sdd backlog start F-001</code>, F-002, …</p></blockquote><hr><h2 id="when-to-use-which-path" tabindex="-1">When to use which path <a class="header-anchor" href="#when-to-use-which-path" aria-label="Permalink to &quot;When to use which path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Command</th></tr></thead><tbody><tr><td>New product discovery</td><td><code>sdd greenfield &quot;…&quot;</code> then <code>sdd complete</code></td></tr><tr><td>Next item from product backlog</td><td><code>sdd backlog start F-001</code></td></tr><tr><td>Feature on existing app (no backlog)</td><td><a href="./simple-feature">Simple feature</a> → <code>sdd new &quot;…&quot;</code></td></tr><tr><td>Tiny fix</td><td><code>sdd new &quot;…&quot; -w hotfix -y</code></td></tr></tbody></table><hr><h2 id="_1-one-time-setup" tabindex="-1">1. One-time setup <a class="header-anchor" href="#_1-one-time-setup" aria-label="Permalink to &quot;1. One-time setup&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-app</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # or an empty folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --here</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> copilot</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # or grok | claude | ollama</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><hr><h2 id="_2-start-from-your-idea" tabindex="-1">2. Start from your idea <a class="header-anchor" href="#_2-start-from-your-idea" aria-label="Permalink to &quot;2. Start from your idea&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> greenfield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Team expense tracker for remote startups&quot;</span></span></code></pre></div><p>You’ll walk four steps (fill a short file each time):</p><ol><li><strong>Vision</strong> — who is it for, problem, how you know MVP worked</li><li><strong>Requirements</strong> — clear “must / should” statements</li><li><strong>Features</strong> — small items <code>F-001</code>, <code>F-002</code>, … (one PR each)</li><li><strong>Architecture</strong> — simple system shape (keep it modest)</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># After writing each file:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> next</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># … until architecture is done …</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> complete</span></span></code></pre></div><p>When you complete, good content is copied into <strong><code>memory/</code></strong> so later work can reuse it:</p><table tabindex="0"><thead><tr><th>You wrote</th><th>Saved as</th></tr></thead><tbody><tr><td>vision</td><td><code>memory/product.md</code></td></tr><tr><td>requirements</td><td><code>memory/requirements.md</code></td></tr><tr><td>features</td><td><code>memory/features.md</code></td></tr><tr><td>architecture</td><td><code>memory/architecture.md</code></td></tr></tbody></table><hr><h2 id="_3-build-features-one-by-one" tabindex="-1">3. Build features one by one <a class="header-anchor" href="#_3-build-features-one-by-one" aria-label="Permalink to &quot;3. Build features one by one&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backlog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backlog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> F-001</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># normal loop: notes → sdd next → code → sdd verify → sdd complete</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backlog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> F-002</span></span></code></pre></div><p>Each start creates a normal change folder and marks that backlog row <strong>in progress</strong>.<br> (Ad-hoc work that is <em>not</em> on the backlog still uses <code>sdd new &quot;…&quot;</code>.)</p><hr><h2 id="how-to-write-a-feature-row" tabindex="-1">How to write a feature row <a class="header-anchor" href="#how-to-write-a-feature-row" aria-label="Permalink to &quot;How to write a feature row&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## F-001: Capture expense</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Status:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> planned</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Priority:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> must</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Workflow:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> feature</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Summary:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> User adds amount, category, and photo receipt.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Requirements:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> R-001</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Notes:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Mobile first</span></span></code></pre></div><p>Headings must look like <code>## F-001: Short name</code> so the tool can read them.</p><hr><h2 id="friendly-tips" tabindex="-1">Friendly tips <a class="header-anchor" href="#friendly-tips" aria-label="Permalink to &quot;Friendly tips&quot;">​</a></h2><ul><li>Keep vision <strong>small</strong> — the smallest useful product.</li><li>One feature ≈ one PR.</li><li>Blank templates don’t get saved into memory — write real sentences.</li><li>First time with sdd? The <a href="./../tutorials/first-change">10-minute tutorial</a> still helps.</li></ul><hr><h2 id="limits-v1" tabindex="-1">Limits (v1) <a class="header-anchor" href="#limits-v1" aria-label="Permalink to &quot;Limits (v1)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Works today</th><th>Not automatic yet</th></tr></thead><tbody><tr><td>List and start F-001…</td><td>Marking features <code>done</code> when a pack completes</td></tr><tr><td>Promote plan into memory</td><td>Syncing edits both ways forever</td></tr><tr><td>Choose workflow per feature</td><td>Multiple products in one repo</td></tr></tbody></table><p>When a feature ships, set <strong>Status</strong> to <code>done</code> in <code>memory/features.md</code> by hand (for now).</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../concepts/change-packs">What is a change pack?</a></li><li><a href="./simple-feature">Simple feature</a></li><li><a href="./everyday-loop">Everyday loop</a></li><li><a href="./../reference/cli">CLI reference</a></li></ul>`,37)])])}const k=t(n,[["render",o]]);export{g as __pageData,k as default};
